package com.campuslibrary.model;

import java.time.LocalDate;

/** Model (generated by scripts/gen_models.py). Plain JavaBean so it can be read from JSP/EL. */
public class Loan {
    private long id;
    private long userId;
    private long bookId;
    private LocalDate borrowedAt;
    private LocalDate dueAt;
    private LocalDate returnedAt;
    private int renewals;
    private String bookTitle;
    private String bookAuthor;
    private String bookIsbn;
    private String bookCoverUrl;
    private long bookCategoryId;
    private String categoryColor;
    private String userName;

    public long getId() { return id; }
    public void setId(long v) { this.id = v; }
    public long getUserId() { return userId; }
    public void setUserId(long v) { this.userId = v; }
    public long getBookId() { return bookId; }
    public void setBookId(long v) { this.bookId = v; }
    public LocalDate getBorrowedAt() { return borrowedAt; }
    public void setBorrowedAt(LocalDate v) { this.borrowedAt = v; }
    public LocalDate getDueAt() { return dueAt; }
    public void setDueAt(LocalDate v) { this.dueAt = v; }
    public LocalDate getReturnedAt() { return returnedAt; }
    public void setReturnedAt(LocalDate v) { this.returnedAt = v; }
    public int getRenewals() { return renewals; }
    public void setRenewals(int v) { this.renewals = v; }
    public String getBookTitle() { return bookTitle; }
    public void setBookTitle(String v) { this.bookTitle = v; }
    public String getBookAuthor() { return bookAuthor; }
    public void setBookAuthor(String v) { this.bookAuthor = v; }
    public String getBookIsbn() { return bookIsbn; }
    public void setBookIsbn(String v) { this.bookIsbn = v; }
    public String getBookCoverUrl() { return bookCoverUrl; }
    public void setBookCoverUrl(String v) { this.bookCoverUrl = v; }
    public long getBookCategoryId() { return bookCategoryId; }
    public void setBookCategoryId(long v) { this.bookCategoryId = v; }
    public String getCategoryColor() { return categoryColor; }
    public void setCategoryColor(String v) { this.categoryColor = v; }
    public String getUserName() { return userName; }
    public void setUserName(String v) { this.userName = v; }

    public static final int FINE_PER_DAY = 1000;
    public boolean isActive() { return returnedAt == null; }
    public boolean isOverdue() { return returnedAt == null && dueAt.isBefore(LocalDate.now()); }
    public int getOverdueDays() {
        LocalDate end = returnedAt != null ? returnedAt : LocalDate.now();
        long d = java.time.temporal.ChronoUnit.DAYS.between(dueAt, end);
        return (int) Math.max(0, d);
    }
    public int getDaysLeft() { return (int) java.time.temporal.ChronoUnit.DAYS.between(LocalDate.now(), dueAt); }
    public boolean isDueSoon() { return returnedAt == null && !isOverdue() && getDaysLeft() <= 3; }
    public long getFine() { return (long) getOverdueDays() * FINE_PER_DAY; }
    public String getStatus() { return returnedAt != null ? "RETURNED" : (isOverdue() ? "OVERDUE" : "ACTIVE"); }
    public boolean isCanRenew() { return returnedAt == null && !isOverdue() && renewals < 2; }
}
